INSERT INTO departments (id, institution_id, name, slug, code, contact_email, about_text) VALUES
('22222222-2222-2222-2222-222222222222', '11111111-1111-1111-1111-111111111111', 'Computer Science & Engineering', 'cse', 'CSE', 'head.cse@nith.ac.in', 'The Department of Computer Science & Engineering offers undergraduate, postgraduate and doctoral programmes with emphasis on contemporary computing research, Artificial Intelligence, Cybersecurity, and High Performance Computing.'),
('22222222-2222-2222-2222-222222222223', '11111111-1111-1111-1111-111111111111', 'Electronics & Communication Engineering', 'ece', 'ECE', 'head.ece@nith.ac.in', 'The Department of Electronics and Communication Engineering imparts education in VLSI design, Wireless Communications, Signal Processing, and IoT systems.'),
('22222222-2222-2222-2222-222222222224', '11111111-1111-1111-1111-111111111111', 'Electrical Engineering', 'ee', 'EE', 'head.ee@nith.ac.in', 'The Department of Electrical Engineering focuses on Power Systems, Smart Grids, Renewable Energy Integration, Control Systems, and Electric Vehicles.'),
('22222222-2222-2222-2222-222222222225', '11111111-1111-1111-1111-111111111111', 'Mechanical Engineering', 'me', 'ME', 'head.me@nith.ac.in', 'The Department of Mechanical Engineering excels in Thermal Engineering, Advanced Manufacturing, Robotics, Fluid Dynamics, and Computational Mechanics.'),
('22222222-2222-2222-2222-222222222226', '11111111-1111-1111-1111-111111111111', 'Civil Engineering', 'ce', 'CE', 'head.ce@nith.ac.in', 'The Department of Civil Engineering offers education and research in Structural Engineering, Geotechnical Engineering, Water Resources, Transportation, and Environmental Engineering.'),
('22222222-2222-2222-2222-222222222227', '11111111-1111-1111-1111-111111111111', 'Chemical Engineering', 'che', 'CHE', 'head.che@nith.ac.in', 'The Department of Chemical Engineering conducts pioneering research in Reaction Engineering, Biochemical Processes, Separation Technologies, and Sustainable Materials.'),
('22222222-2222-2222-2222-222222222228', '11111111-1111-1111-1111-111111111111', 'Material Science & Engineering', 'mse', 'MSE', 'head.mse@nith.ac.in', 'The Department of Material Science & Engineering explores Nanomaterials, Biomaterials, Smart Alloys, and Advanced Functional Materials.'),
('22222222-2222-2222-2222-222222222229', '11111111-1111-1111-1111-111111111111', 'Department of Architecture', 'arch', 'ARCH', 'head.arch@nith.ac.in', 'The Department of Architecture promotes Sustainable Architecture, Urban Planning, Heritage Conservation, and Energy Efficient Building Design.'),
('22222222-2222-2222-2222-222222222230', '11111111-1111-1111-1111-111111111111', 'Mathematics & Scientific Computing', 'maths', 'MATHS', 'head.maths@nith.ac.in', 'The Department offers training in Pure & Applied Mathematics, Numerical Analysis, Cryptography, and Scientific Computing.'),
('22222222-2222-2222-2222-222222222231', '11111111-1111-1111-1111-111111111111', 'Physics & Photonics Science', 'physics', 'PHYSICS', 'head.physics@nith.ac.in', 'The Department engages in Condensed Matter Physics, Optics, Photonics, High Energy Physics, and Quantum Computing.'),
('22222222-2222-2222-2222-222222222232', '11111111-1111-1111-1111-111111111111', 'Department of Chemistry', 'chem', 'CHEM', 'head.chem@nith.ac.in', 'The Department conducts cutting-edge research in Synthetic Organic, Inorganic, Physical and Computational Chemistry.'),
('22222222-2222-2222-2222-222222222233', '11111111-1111-1111-1111-111111111111', 'Humanities & Social Sciences', 'hss', 'HSS', 'head.hss@nith.ac.in', 'The Department nurtures critical thinking and communication through studies in Literature, Economics, Psychology, and Sociology.'),
('22222222-2222-2222-2222-222222222234', '11111111-1111-1111-1111-111111111111', 'Department of Management Studies', 'doms', 'DOMS', 'head.doms@nith.ac.in', 'The Department of Management Studies offers MBA and doctoral research in Marketing, Finance, HR, Operations, and Business Analytics.'),
('22222222-2222-2222-2222-222222222235', '11111111-1111-1111-1111-111111111111', 'Centre for Energy Studies', 'ces', 'CES', 'head.ces@nith.ac.in', 'Established in 2009, this centre leads interdisciplinary research in Solar Thermal, Photovoltaics, Biofuels, and Energy Management.')
